//! The direct-transfer integrity receipt construction (ADR-0194 section 2). Pure functions over bytes: no state, no I/O.
//! The state machine that uses it is `direct.rs`; the independent vectors are
//! `verification/vectors/direct-transfer-receipt-vectors.json.gz` (generated by
//! `verification/prototypes/direct-receipt/`, replayed by `tests/direct_receipt_vectors.rs`).
//!
//! Notation: OM-CBOR is the canonical deterministic CBOR of `CANONICAL_ENCODING.md`; `DS-HASH(label, body)` is the
//! registry construction (raw 32-byte SHA-256, as `ds_hash`); HKDF is HKDF-SHA-256 (RFC 5869); HMAC is HMAC-SHA-256.

use super::cbor::{self, V};
use super::kdf::{hkdf_sha256, hmac_sha256};
use super::sig::ds_hash;
use zeroize::Zeroize;

/// `kdf`: expand info of the receipt key.
pub const LBL_KDF: &str = "OM-DIRECT-RECEIPT-KDF-v1";
/// `mac`: the receipt tag.
pub const LBL_MAC: &str = "OM-DIRECT-RECEIPT-MAC-v1";
/// `hash`: the possession hash over the transfer id and the whole object.
pub const LBL_POSSESSION: &str = "OM-DIRECT-RECEIPT-POSSESSION-HASH-v1";

/// `K_rcpt = HKDF(salt = ciphertext_digest, IKM = content_key, info = OM-CBOR [ LBL_KDF, blob_id ], 32)`.
pub fn receipt_key(
    content_key: &[u8; 32],
    ciphertext_digest: &[u8; 32],
    blob_id: &[u8; 32],
) -> [u8; 32] {
    let info = cbor::encode(&V::A(vec![V::T(LBL_KDF.into()), V::B(blob_id.to_vec())]));
    let mut out = [0u8; 32];
    hkdf_sha256(ciphertext_digest, content_key, &info, &mut out);
    out
}

/// `H_pos = DS-HASH(LBL_POSSESSION, OM-CBOR [ transfer_id, ciphertext ])`.
pub fn possession_hash(transfer_id: &[u8; 16], ciphertext: &[u8]) -> [u8; 32] {
    ds_hash(
        LBL_POSSESSION,
        &cbor::encode(&V::A(vec![
            V::B(transfer_id.to_vec()),
            V::B(ciphertext.to_vec()),
        ])),
    )
}

/// The receipt tag for `transfer_id`: `HMAC(K_rcpt, OM-CBOR [ LBL_MAC, transfer_id, blob_id, total_bytes,
/// ciphertext_digest, H_pos ])`. `total_bytes` is the object length (`ciphertext.len()`).
pub fn receipt_tag(
    content_key: &[u8; 32],
    ciphertext_digest: &[u8; 32],
    blob_id: &[u8; 32],
    transfer_id: &[u8; 16],
    ciphertext: &[u8],
) -> [u8; 32] {
    tag_from_parts(
        content_key,
        ciphertext_digest,
        blob_id,
        transfer_id,
        ciphertext.len() as u64,
        &possession_hash(transfer_id, ciphertext),
    )
}

/// The tag from its already computed parts (the vectors vary each input on its own).
pub fn tag_from_parts(
    content_key: &[u8; 32],
    ciphertext_digest: &[u8; 32],
    blob_id: &[u8; 32],
    transfer_id: &[u8; 16],
    total_bytes: u64,
    h_pos: &[u8; 32],
) -> [u8; 32] {
    let mut k = receipt_key(content_key, ciphertext_digest, blob_id);
    let input = cbor::encode(&V::A(vec![
        V::T(LBL_MAC.into()),
        V::B(transfer_id.to_vec()),
        V::B(blob_id.to_vec()),
        V::U(total_bytes),
        V::B(ciphertext_digest.to_vec()),
        V::B(h_pos.to_vec()),
    ]));
    let tag = hmac_sha256(&k, &input);
    k.zeroize();
    tag
}
